{
    int n = argc + 2;
    (void)argv;

    int r1 = add(n, 5);
    long long r2 = sum6(1, 2, 3, 4, n, 6);
    int r3 = scale(n);
    double r4 = mix(n, 1.5, 2, 0.5f);
    int r5 = shout(n);

    printf("%d %lld %d %f %d\n", r1, r2, r3, r4, r5);
    return 0;
}

